WITH promo_sales AS (SELECT p.p_promo_sk, p.p_promo_name, i.i_product_name, p.p_cost AS promo_cost, p.p_response_target AS promo_response_target, SUM(ws.ws_ext_sales_price) AS total_sales, SUM(ws.ws_ext_discount_amt) AS total_discount, SUM(ws.ws_net_profit) AS total_profit, AVG(hd.hd_vehicle_count) AS avg_vehicle_count FROM promotion p INNER JOIN web_sales ws ON p.p_promo_sk = ws.ws_promo_sk INNER JOIN item i ON p.p_item_sk = i.i_item_sk INNER JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk GROUP BY p.p_promo_sk, p.p_promo_name, i.i_product_name, p.p_cost, p.p_response_target) SELECT p_promo_sk, p_promo_name, i_product_name, total_sales, total_discount, ROUND(100.0 * total_discount / NULLIF(total_sales, 0), 2) AS discount_ratio_percent, promo_cost AS total_cost, promo_response_target AS total_response_target, avg_vehicle_count, CASE WHEN total_sales = 0 THEN NULL ELSE ROUND(1.0 * total_profit / promo_cost, 2) END AS profit_per_cost, DENSE_RANK() OVER (ORDER BY total_discount / NULLIF(total_sales, 0) DESC) AS discount_rank, ROW_NUMBER() OVER (PARTITION BY p_promo_name ORDER BY total_sales DESC) AS sales_rank_per_promo FROM promo_sales WHERE total_sales > 0 ORDER BY discount_rank
